INSERT INTO public.companies (slug, name, subsector_id, website, chains, tags, meta)
SELECT v.slug, v.name, s.id, v.website, v.chains, v.tags, v.meta
FROM (VALUES
  ('polygon-cdk', 'Polygon CDK', 'rollup-scaling-frameworks', 'l3-appchain-frameworks', 'https://polygon.technology/cdk', ARRAY['Polygon zkEVM architecture (SNARK-based validity proofs).']::text[], ARRAY['ZK rollup', 'appchain', 'L3 framework.']::text[], '{"description": "A modular ZK rollup and appchain development kit that enables teams to launch Ethereum-anchored zkEVM rollups and L3s using Polygon’s SNARK-based validity-proof infrastructure.", "extras": {"Base Layer Dependency": "Ethereum L1; optional ecosystem hubs within Polygon.", "Bespoke Engineering Required": "Limited — teams primarily configure parameters and infrastructure.", "Composability with Base Rollup": "Asynchronous composability with Ethereum and Polygon-aligned chains.", "Configurable Parameters": "Gas pricing, block times, fee routing, DA mode, sequencer configuration.", "Cross-Rollup Messaging Assumptions": "Relies on standardized Polygon messaging patterns; not natively synchronous.", "Dependency Concentration Risk": "High dependency on Polygon Labs for protocol evolution and proving infrastructure.", "Does This Enable L3s": "Yes — supports L3-style zk appchains settling to Ethereum directly or via L2 hubs.", "Ecosystem Alignment": "Strong alignment with the broader Polygon ZK ecosystem.", "Emergency Controls": "Emergency pause and intervention mechanisms exist at framework and chain levels.", "Execution Environment Options": "EVM-equivalent (zkEVM bytecode-level compatibility).", "External Bridge Dependency": "Required for interoperability outside the Polygon ecosystem.", "Failure Propagation Model": "L3 → L2 (if used) → L1, depending on deployment topology.", "Fault / Validity Proof Inheritance": "Inherits SNARK-based validity-proof system defined by Polygon CDK.", "Fixed vs Variable Costs": "High fixed prover costs; variable costs scale with usage and L1 gas prices.", "Framework Ownership": "Developed and maintained by Polygon Labs.", "Infrastructure Responsibility Split": "Deployers manage chain infra; Polygon provides protocol, prover stack, and tooling.", "Isolation vs Shared Security": "Execution isolated per chain; proving and settlement standards shared.", "Latency Trade-offs": "Improved scalability and lower fees at the cost of additional settlement layers.", "Level of Protocol Abstraction": "High — standardized contracts, prover infrastructure, and deployment workflows.", "Native Interoperability Support": "Best within the Polygon zkEVM / CDK ecosystem.", "Number of Chains Deployed": "Growing number of zkEVM-based appchains and rollups launched or announced.", "Operational Complexity": "Medium–high — ZK proving infrastructure increases complexity versus optimistic stacks.", "Path to Sovereignty": "Moderate — deployers gain operational control but remain coupled to Polygon CDK evolution.", "Practitioner Validation Check": "If Polygon CDK were removed, teams would need to design zkEVM circuits, proving pipelines, and Ethereum settlement logic independently to deploy Polygon-style ZK rollups.", "Practitioner''s Note": "Polygon CDK is best viewed as a ZK appchain factory optimized for teams that want zkEVM compatibility plus ecosystem alignment with Polygon, rather than a single shared rollup environment.", "Reason of inclusion": "Defines standardized deployment pipelines, execution templates, and settlement models that allow teams to launch ZK rollups and appchains without building ZK protocol infrastructure from scratch.", "Security Inheritance": "Configurable:\n- Full Ethereum security for rollup deployments\n- Partial security for validium-style deployments (off-chain DA)", "Sequencer Model Options": "Single sequencer per chain by default; decentralization options roadmap-driven.", "Settlement Layer": "Ethereum L1 (direct settlement).", "Types of Users": "Application teams, enterprises, and ecosystems seeking zkEVM compatibility with Polygon alignment.", "Upgrade Model": "Framework-level upgrades coordinated by Polygon; per-chain upgrades possible within constraints.", "Vendor Lock-in Risk": "Moderate–high — tight coupling to Polygon zkEVM and CDK roadmap.", "Who Controls Upgrades": "Framework upgrades governed by Polygon; deployers control chain-level parameters."}, "source_label": "L3 & Appchain Frameworks"}'::jsonb),
  ('avalanche-hypersdk-ethereum-anchored-variants-only', 'Avalanche HyperSDK (Ethereum-anchored variants only)', 'rollup-scaling-frameworks', 'l3-appchain-frameworks', 'https://docs.avax.network/build/hypersdk', ARRAY['Custom execution VM with Ethereum anchoring via settlement or security bridges (not a native rollup engine).']::text[], ARRAY['Appchain', 'L3 framework (custom VM–based).']::text[], '{"description": "A high-performance appchain SDK developed by Avalanche that enables teams to build custom virtual machines and application-specific chains, including configurations that anchor settlement or security back to Ethereum.", "extras": {"Base Layer Dependency": "Ethereum L1 (optional and configuration-dependent).", "Bespoke Engineering Required": "Moderate — protocol engineering avoided, but VM logic must be defined.", "Composability with Base Rollup": "Not applicable — interaction occurs via settlement/bridges.", "Configurable Parameters": "State model, transaction semantics, gas logic, block production rules, fee mechanics.", "Cross-Rollup Messaging Assumptions": "Requires external messaging or bridge infrastructure.", "Dependency Concentration Risk": "Moderate dependency on Avalanche tooling and SDK evolution.", "Does This Enable L3s": "Yes — HyperSDK chains can function as L3-style appchains when anchored to Ethereum.", "Ecosystem Alignment": "Stronger alignment with Avalanche ecosystem; Ethereum anchoring is secondary.", "Emergency Controls": "Defined at the chain level; no enforced framework-level safeguards.", "Execution Environment Options": "Custom VM (non-EVM by default; EVM-like behavior must be explicitly implemented).", "External Bridge Dependency": "Yes — required for Ethereum interaction.", "Failure Propagation Model": "Appchain failures do not propagate automatically; settlement anchoring defines recovery paths.", "Fault / Validity Proof Inheritance": "None by default — HyperSDK chains do not natively inherit rollup-style fraud or validity proofs.", "Fixed vs Variable Costs": "High fixed engineering and infra costs; low marginal execution costs.", "Framework Ownership": "Developed and maintained by Avalanche Labs.", "Infrastructure Responsibility Split": "Primarily on chain deployer; Avalanche provides SDK only.", "Isolation vs Shared Security": "Fully isolated execution; shared security only if explicitly engineered.", "Latency Trade-offs": "Very high throughput and low latency at the cost of weaker native Ethereum coupling.", "Level of Protocol Abstraction": "High — VM templates, networking, and consensus primitives provided.", "Native Interoperability Support": "None natively with Ethereum rollups.", "Number of Chains Deployed": "Limited for Ethereum-anchored variants; HyperSDK adoption stronger in non-Ethereum contexts.", "Operational Complexity": "High — teams must manage VM logic, infrastructure, and Ethereum anchoring.", "Path to Sovereignty": "High — chains are highly sovereign by design.", "Practitioner Validation Check": "If Ethereum-anchored HyperSDK deployments were removed, teams seeking custom VM appchains with Ethereum settlement/security would need to build bespoke execution and settlement logic.", "Practitioner''s Note": "HyperSDK should be evaluated as a maximum-flexibility appchain framework. Ethereum anchoring is optional and configuration-dependent; not all HyperSDK chains qualify for this subsector.", "Reason of inclusion": "Provides a framework that allows teams to launch Ethereum-anchored appchains with custom execution environments without building chain logic from scratch, when configured for Ethereum settlement or security anchoring.", "Security Inheritance": "Partial and configurable — depends on how Ethereum anchoring is implemented (not inherent like rollups).", "Sequencer Model Options": "Chain-defined block production (single or multi-producer depending on design).", "Settlement Layer": "Ethereum L1 (via settlement or security anchoring mechanisms).", "Types of Users": "Advanced teams needing custom execution semantics.", "Upgrade Model": "Chain-defined upgrades, governed by deployer-chosen governance.", "Vendor Lock-in Risk": "Low-to-moderate — SDK dependency, but execution logic is custom-owned.", "Who Controls Upgrades": "Chain deployers fully control upgrades and governance."}, "source_label": "L3 & Appchain Frameworks"}'::jsonb),
  ('caldera', 'Caldera', 'rollup-scaling-frameworks', 'l3-appchain-frameworks', 'https://www.caldera.xyz', ARRAY['Configurable: OP Stack', 'Arbitrum Nitro', 'and selected ZK rollup frameworks.']::text[], ARRAY['Rollup deployment platform', 'appchain launcher.']::text[], '{"description": "A rollup deployment platform that enables teams to launch Ethereum-anchored rollups and appchains using existing rollup frameworks (e.g., OP Stack, Arbitrum Nitro, ZK stacks) without managing low-level protocol engineering or infrastructure.", "extras": {"Base Layer Dependency": "Ethereum L1 via chosen L2 / rollup framework.", "Bespoke Engineering Required": "Minimal — primarily parameter selection and application integration.", "Composability with Base Rollup": "Asynchronous composability via base rollup and Ethereum settlement.", "Configurable Parameters": "Gas model, block time, fee routing, sequencer setup, DA options (framework-dependent).", "Cross-Rollup Messaging Assumptions": "Framework-dependent; typically external messaging layers required.", "Dependency Concentration Risk": "Dependency on Caldera’s platform and supported framework roadmap.", "Does This Enable L3s": "Yes — supports L3-style appchains when deployed on top of L2 rollups.", "Ecosystem Alignment": "Strong alignment with OP Stack and Arbitrum ecosystems.", "Emergency Controls": "Operational safeguards provided by Caldera; ultimate authority depends on framework and deployer setup.", "Execution Environment Options": "Inherited from underlying framework (typically EVM-equivalent).", "External Bridge Dependency": "Yes — required for interoperability beyond the chosen ecosystem.", "Failure Propagation Model": "Appchain → base rollup → Ethereum, depending on topology.", "Fault / Validity Proof Inheritance": "Inherited from OP Stack, Nitro, or ZK framework used.", "Fixed vs Variable Costs": "Recurring platform fees plus variable costs tied to usage and L1 data posting.", "Framework Ownership": "Developed and operated by Caldera.", "Infrastructure Responsibility Split": "Caldera manages infra; deployers manage applications and governance choices.", "Isolation vs Shared Security": "Execution isolated per chain; security assumptions shared with upstream framework.", "Latency Trade-offs": "Lower fees and faster UX with additional settlement layers.", "Level of Protocol Abstraction": "Very high — protocol logic is inherited; deployers focus on configuration.", "Native Interoperability Support": "Inherited from the underlying rollup framework.", "Number of Chains Deployed": "Multiple production and announced rollups across gaming, DeFi, and consumer apps.", "Operational Complexity": "Low-to-medium — significantly reduced versus self-operated rollups.", "Path to Sovereignty": "Moderate — deployers gain operational control but remain dependent on Caldera and underlying frameworks.", "Practitioner Validation Check": "If Caldera were removed, many teams would need to directly integrate OP Stack, Nitro, or ZK frameworks and operate infra in-house to launch Ethereum-anchored chains.", "Practitioner''s Note": "Caldera is best evaluated as “rollups-as-a-service”: it does not define rollup mechanics, but it meaningfully lowers the barrier to deploying and operating them.", "Reason of inclusion": "Standardizes and abstracts the rollup deployment pipeline—configuration, infrastructure, and lifecycle management—allowing teams to launch Ethereum-settled chains without building or operating rollup protocol logic themselves.", "Security Inheritance": "Inherited entirely from the selected rollup stack (optimistic or ZK).", "Sequencer Model Options": "Inherited from base framework; operated or coordinated via Caldera.", "Settlement Layer": "Ethereum L1 (directly or indirectly via the chosen rollup framework).", "Types of Users": "Application teams prioritizing speed-to-market over protocol ownership.", "Upgrade Model": "Framework upgrades flow from the underlying stack; deployer controls application-level upgrades.", "Vendor Lock-in Risk": "Moderate — migration requires re-deploying or re-operating the rollup independently.", "Who Controls Upgrades": "Protocol upgrades controlled by upstream framework governance; deployers control appchain configuration."}, "source_label": "L3 & Appchain Frameworks"}'::jsonb),
  ('conduit', 'Conduit', 'rollup-scaling-frameworks', 'l3-appchain-frameworks', 'https://www.conduit.xyz', ARRAY['Primarily OP Stack (with ecosystem integrations).']::text[], ARRAY['Rollup deployment platform', 'managed infrastructure layer.']::text[], '{"description": "A rollup deployment and infrastructure platform that enables teams to launch and operate Ethereum-anchored rollups and appchains (primarily OP Stack–based) without running core infrastructure themselves.", "extras": {"Base Layer Dependency": "Ethereum L1 or OP Stack L2s (deployment-dependent).", "Bespoke Engineering Required": "Minimal — application integration and parameter selection only.", "Composability with Base Rollup": "Asynchronous composability with Ethereum and OP Stack peers.", "Configurable Parameters": "Gas pricing, block time, fee routing, sequencer configuration, DA provider selection.", "Cross-Rollup Messaging Assumptions": "Relies on OP Stack messaging patterns and external layers.", "Dependency Concentration Risk": "High dependency on Conduit operations and OP Stack roadmap.", "Does This Enable L3s": "Yes — supports L3-style appchains when deployed on top of OP Stack L2s.", "Ecosystem Alignment": "Strong alignment with OP Stack / Superchain ecosystem.", "Emergency Controls": "Operational safeguards and incident response handled by Conduit; ultimate authority depends on OP Stack and deployer governance.", "Execution Environment Options": "Inherited from OP Stack (EVM-equivalent).", "External Bridge Dependency": "Yes — required for interoperability outside OP Stack ecosystem.", "Failure Propagation Model": "L3 → L2 → L1, depending on topology.", "Fault / Validity Proof Inheritance": "Inherits OP Stack fraud-proof and challenge-window model.", "Fixed vs Variable Costs": "Recurring platform fees plus variable costs tied to usage and L1 posting.", "Framework Ownership": "Developed and operated by Conduit.", "Infrastructure Responsibility Split": "Conduit manages infra; deployers manage apps and governance decisions.", "Isolation vs Shared Security": "Execution isolated per chain; security assumptions shared with OP Stack.", "Latency Trade-offs": "Lower fees and faster UX with additional settlement hops.", "Level of Protocol Abstraction": "Very high — deployers interact with configuration, not protocol internals.", "Native Interoperability Support": "Inherited from OP Stack / Superchain standards.", "Number of Chains Deployed": "Multiple production OP Stack–based chains launched via Conduit.", "Operational Complexity": "Low — Conduit handles infra, monitoring, and ops.", "Path to Sovereignty": "Low-to-moderate — strong operational dependence on Conduit and OP Stack.", "Practitioner Validation Check": "If Conduit were removed, teams would need to self-operate OP Stack (or equivalent) infrastructure to launch and maintain Ethereum-anchored rollups.", "Practitioner''s Note": "Conduit is best evaluated as “managed rollup infrastructure”, not a framework defining execution or settlement logic. It abstracts ops, not protocol design.", "Reason of inclusion": "Standardizes and operationalizes the rollup launch lifecycle—deployment, sequencing, data availability integration, upgrades, and monitoring—allowing teams to ship Ethereum-settled chains without bespoke protocol or infra engineering.", "Security Inheritance": "Full Ethereum settlement security under optimistic assumptions.", "Sequencer Model Options": "Single sequencer operated/managed via Conduit; decentralization depends on OP Stack roadmap.", "Settlement Layer": "Ethereum L1 (direct settlement via OP Stack).", "Types of Users": "Application teams prioritizing speed, reliability, and managed ops.", "Upgrade Model": "Framework upgrades follow OP Stack evolution; deployers manage app-level upgrades.", "Vendor Lock-in Risk": "Moderate — migration requires standing up self-hosted OP Stack infra.", "Who Controls Upgrades": "Core protocol upgrades driven by OP Stack governance; deployers control chain configuration."}, "source_label": "L3 & Appchain Frameworks"}'::jsonb),
  ('starkex-validium-zk-rollup-modes-application-specific', 'StarkEx
(Validium + ZK Rollup modes; application-specific)', 'rollup-scaling-frameworks', 'validiums-volitions-hybrid-rollups', 'https://starkware.co/starkex', ARRAY[]::text[], ARRAY[]::text[], '{"description": "A ZK-based execution engine that enables applications to operate as Validiums or ZK Rollups, anchoring settlement and validity proofs to Ethereum while moving data availability off-chain.", "extras": {"Bridge Dependency": "Yes — required for all cross-chain interaction", "Censorship Risk": "High — sequencer and DA provider are permissioned", "Compatibility with Rollup": "Limited — requires bridges and custom integrations", "Composability with Ethereum": "Asynchronous; settlement only", "Cost Reduction vs Ethereum DA": "Very high (primary motivation for Validium design)", "DA Committee Governance": "Highly centralized; membership and rules defined per deployment", "DA Location": "Off-chain (application-specific DA committee or provider)", "DA Mode Switching": "Protocol / deployment-level (not user-selectable)", "DA Provider Type": "Permissioned DA committee or operator-managed availability service", "DA Withholding Risk": "Yes — DA committee can withhold data", "Data Unavailability Scenarios": "DA committee/operator outage or malicious withholding", "Ecosystem Lock-in Risk": "High — tightly coupled to StarkWare infrastructure", "Emergency Intervention Powers": "Strong operator-level intervention and pause capabilities", "Execution Proof Type": "ZK validity proofs (STARK-based)", "Failure Blast Radius": "Application-specific (does not propagate to Ethereum or other rollups)", "Latency Characteristics": "Low latency relative to rollups due to off-chain DA and batching", "Longevity / Migration Risk": "Moderate — migration to full rollup possible but non-trivial", "Migration Path to Full Rollup": "Possible but costly; requires DA redesign and contract migration", "Operational Complexity": "High — requires DA committee coordination and custom ops", "Practitioner Validation Check": "If StarkEx were removed, affected applications would lose their off-chain DA + Ethereum-verified validity-proof execution model, materially changing where DA risk is borne.", "Practitioner’s Note": "StarkEx is not a shared rollup network. Each deployment is application-specific, highly optimized, and trades Ethereum DA guarantees for performance and cost efficiency.", "Primary User Type": "Sophisticated applications prioritizing performance over trust minimization", "Production Usage Signal": "Long-running production deployments at scale", "Protocol Ownership": "StarkWare (in collaboration with application operator)", "Reason for Inclusion": "Implements production off-Ethereum data availability with Ethereum-anchored validity proofs, explicitly defining DA committees, trust assumptions, and recovery behavior.", "Recovery Guarantees if DA Fails": "Limited; Ethereum verifies correctness but cannot reconstruct state without DA", "Rollup Variant": "Validium (with optional ZK Rollup mode depending on deployment)", "Security Lost vs Full Rollup": "Loss of Ethereum-guaranteed data availability and forced user exit", "Settlement Layer": "Ethereum L1", "Throughput Improvements": "Significant — optimized for high-frequency, high-volume workloads", "Upgrade Authority": "Centralized — upgrades coordinated by StarkWare and application operator", "Use-Case Fit": "High-throughput trading, gaming, NFTs, enterprise-style workloads", "User Exit Risk": "High — users may be unable to exit if DA is unavailable", "What Ethereum Verifies": "Validity proofs and state commitments (not transaction data)", "Who Ultimately Controls DA": "Application operator in coordination with StarkWare-defined DA architecture"}, "source_label": "Validiums, Volitions, and Hybrid Rollups"}'::jsonb),
  ('zk-stack-rollup-vs-validium-selectable-at-deployment', 'ZK Stack
(Rollup vs Validium selectable at deployment)', 'rollup-scaling-frameworks', 'validiums-volitions-hybrid-rollups', 'https://zksync.io/zk-stack', ARRAY[]::text[], ARRAY[]::text[], '{"description": "A modular ZK rollup framework that enables teams to deploy Ethereum-anchored rollups, validiums, and hybrid (volition-style) chains, with configurable data availability modes and shared proving infrastructure.", "extras": {"Bridge Dependency": "Yes — required for cross-ecosystem interaction", "Censorship Risk": "Moderate-to-high in validium mode due to permissioned sequencing/DA", "Compatibility with Rollup": "Higher within the ZK Stack ecosystem; limited externally without bridges", "Composability with Ethereum": "Asynchronous; strongest in rollup mode", "Cost Reduction vs Ethereum DA": "High in validium mode; moderate-to-none in rollup mode", "DA Committee Governance": "Defined per deployment; typically permissioned and centrally coordinated", "DA Location": "Configurable — Ethereum DA (rollup) or off-chain DA (validium)", "DA Mode Switching": "Protocol / deployment-level (framework-configurable; not typically user-selectable at runtime)", "DA Provider Type": "Permissioned DA committee or operator-managed off-chain DA service (configurable per deployment)", "DA Withholding Risk": "Yes — present in validium modes; mitigated only in full rollup mode", "Data Unavailability Scenarios": "DA committee outage, misconfiguration, or malicious withholding", "Ecosystem Lock-in Risk": "Moderate–high due to shared proving stack and framework coupling", "Emergency Intervention Powers": "Present at both framework and chain levels", "Execution Proof Type": "ZK validity proofs (SNARK-based)", "Failure Blast Radius": "Deployment-specific; failures do not propagate beyond the affected chain", "Latency Characteristics": "Lower latency achievable when DA is off-chain; finality still gated by proof verification", "Longevity / Migration Risk": "Moderate; migration from validium to rollup is supported but operationally complex", "Migration Path to Full Rollup": "Yes — framework-supported, but requires DA and contract reconfiguration", "Operational Complexity": "Medium–high; DA configuration and monitoring add complexity beyond pure rollups", "Practitioner Validation Check": "If ZK Stack were removed, teams would need to rebuild ZK execution, proving, DA logic, and Ethereum settlement plumbing to offer validium or hybrid DA modes.", "Practitioner’s Note": "ZK Stack is best evaluated as configurable ZK infrastructure: the DA model is a first-class design choice that materially changes user exit guarantees, costs, and performance.", "Primary User Type": "Teams seeking ZK security with flexible cost/performance trade-offs", "Production Usage Signal": "Growing number of zkChains deploying with non-Ethereum DA configurations", "Protocol Ownership": "Framework stewarded by Matter Labs; chain-level control held by deployers", "Reason for Inclusion": "Explicitly defines off-Ethereum DA options, DA trust assumptions, and configurable DA switching while anchoring validity proofs and settlement to Ethereum.", "Recovery Guarantees if DA Fails": "- Rollup mode: Ethereum-enforced user exit\n- Validium mode: limited; correctness holds but data recovery is not guaranteed", "Rollup Variant": "Hybrid (supports ZK Rollup, Validium, and Volition-style configurations)", "Security Lost vs Full Rollup": "Loss of Ethereum-guaranteed DA and forced exits in validium mode", "Settlement Layer": "Ethereum L1", "Throughput Improvements": "High in validium/hybrid configurations due to reduced calldata costs", "Upgrade Authority": "Framework upgrades governed centrally; chain upgrades controlled by deployers within framework constraints", "Use-Case Fit": "Gaming, consumer apps, enterprise workloads, and high-volume applications with DA tolerance", "User Exit Risk": "Present in validium mode; absent in full rollup mode", "What Ethereum Verifies": "Validity proofs and state commitments (transaction data only in rollup mode)", "Who Ultimately Controls DA": "Chain deployer and framework-defined governance (subject to configuration)"}, "source_label": "Validiums, Volitions, and Hybrid Rollups"}'::jsonb),
  ('polygon-cdk-supports-zkevm-rollups-validium-style-chains', 'Polygon CDK
(Supports zkEVM rollups + validium-style chains)', 'rollup-scaling-frameworks', 'validiums-volitions-hybrid-rollups', 'https://polygon.technology/cdk', ARRAY[]::text[], ARRAY[]::text[], '{"description": "A modular ZK rollup framework enabling teams to deploy Ethereum-anchored zkEVM chains in validium mode, anchoring validity proofs to Ethereum while moving data availability off-chain for cost and throughput gains.", "extras": {"Bridge Dependency": "Yes — required for cross-ecosystem interaction", "Censorship Risk": "Moderate-to-high due to permissioned DA and sequencing", "Compatibility with Rollup": "Limited without bridges; stronger within Polygon-aligned ecosystems", "Composability with Ethereum": "Asynchronous; weaker than full rollups", "Cost Reduction vs Ethereum DA": "Very high (primary motivation)", "DA Committee Governance": "Defined per deployment; typically permissioned and centrally coordinated", "DA Location": "Off-chain (permissioned DA committee or operator-managed service)", "DA Mode Switching": "Deployment-level (static at launch; migration path supported)", "DA Provider Type": "Permissioned DA committee or operator-managed DA service (configurable)", "DA Withholding Risk": "Yes — DA providers can withhold data", "Data Unavailability Scenarios": "DA committee outage, misconfiguration, or malicious withholding", "Ecosystem Lock-in Risk": "Moderate–high due to coupling to Polygon CDK tooling and prover stack", "Emergency Intervention Powers": "Present at both framework and chain levels", "Execution Proof Type": "ZK validity proofs (SNARK-based)", "Failure Blast Radius": "Chain-specific; does not propagate beyond the affected deployment", "Latency Characteristics": "Lower latency achievable; finality gated by proof generation/verification", "Longevity / Migration Risk": "Moderate; migration to full rollup supported but operationally complex", "Migration Path to Full Rollup": "Yes — supported via redeployment/reconfiguration of DA and contracts", "Operational Complexity": "Medium–high; DA ops and monitoring add complexity", "Practitioner Validation Check": "If Polygon CDK validium mode were removed, teams would need to build custom zkEVM circuits, DA logic, and Ethereum settlement plumbing to achieve off-chain DA.", "Practitioner’s Note": "Polygon CDK validiums are best suited for teams that want zkEVM compatibility with materially lower DA costs, while accepting explicit DA trust assumptions and exit-risk trade-offs.", "Primary User Type": "Teams prioritizing cost efficiency and throughput over maximum trust minimization", "Production Usage Signal": "Growing number of Polygon-aligned zkEVM chains opting for validium economics", "Protocol Ownership": "Framework developed by Polygon Labs; chain controlled by deployer", "Reason for Inclusion": "Defines off-Ethereum DA configurations, DA provider/committee logic, and settlement anchoring to Ethereum, making DA placement a first-class, configurable design choice.", "Recovery Guarantees if DA Fails": "Limited; Ethereum verifies correctness but cannot reconstruct state without DA", "Rollup Variant": "Validium (with optional migration to rollup mode)", "Security Lost vs Full Rollup": "Loss of Ethereum-guaranteed DA and forced exits", "Settlement Layer": "Ethereum L1", "Throughput Improvements": "High — calldata constraints removed", "Upgrade Authority": "Framework upgrades governed by Polygon; chain-level upgrades by deployer", "Use-Case Fit": "Gaming, consumer apps, high-volume enterprise workflows, cost-sensitive DeFi", "User Exit Risk": "High — users may be unable to exit if DA is unavailable", "What Ethereum Verifies": "Validity proofs and state commitments (not transaction data)", "Who Ultimately Controls DA": "Chain deployer and DA committee governance defined at deployment"}, "source_label": "Validiums, Volitions, and Hybrid Rollups"}'::jsonb),
  ('zksync-era-implements-volition-style-da-choice-in-practice', 'zkSync Era
(Implements Volition-style DA choice in practice)', 'rollup-scaling-frameworks', 'validiums-volitions-hybrid-rollups', 'https://zksync.io', ARRAY[]::text[], ARRAY[]::text[], '{"description": "An Ethereum L2 ZK rollup that supports volition-style data availability, allowing applications or deployments to choose between Ethereum DA and off-chain DA, while anchoring validity proofs and settlement to Ethereum.", "extras": {"Bridge Dependency": "Yes — required for cross-ecosystem interaction", "Censorship Risk": "Moderate — sequencing and DA are permissioned in non-Ethereum DA configurations", "Compatibility with Rollup": "High within zkSync ecosystem; limited externally without bridges", "Composability with Ethereum": "Asynchronous; strongest when Ethereum DA is used", "Cost Reduction vs Ethereum DA": "High when off-chain DA is used; none when using Ethereum DA", "DA Committee Governance": "Defined per deployment; typically permissioned and centrally coordinated", "DA Location": "Configurable — Ethereum DA or off-chain DA", "DA Mode Switching": "Protocol / deployment-level (not typically user-selectable per transaction)", "DA Provider Type": "Permissioned DA committee or operator-managed off-chain DA service (for non-Ethereum DA mode)", "DA Withholding Risk": "Present in off-chain DA mode; absent when Ethereum DA is used", "Data Unavailability Scenarios": "DA committee outage, misconfiguration, or malicious withholding in off-chain DA mode", "Ecosystem Lock-in Risk": "Moderate — dependence on zkSync tooling and proving infrastructure", "Emergency Intervention Powers": "Present at protocol and operator levels", "Execution Proof Type": "ZK validity proofs (SNARK-based)", "Failure Blast Radius": "Configuration-specific; DA failures affect only deployments using off-chain DA", "Latency Characteristics": "Lower latency achievable in off-chain DA mode; finality still gated by proof verification", "Longevity / Migration Risk": "Low–moderate; migration between DA modes is supported but operationally non-trivial", "Migration Path to Full Rollup": "Yes — Ethereum DA mode provides a direct path to full rollup guarantees", "Operational Complexity": "Medium — additional DA configuration and monitoring required", "Practitioner Validation Check": "If zkSync Era’s volition capabilities were removed, teams would lose the ability to opt out of Ethereum DA while retaining Ethereum-anchored validity proofs, forcing a binary choice between full rollups and validiums.", "Practitioner’s Note": "zkSync Era in volition usage is best understood as a selective trust system: correctness is always Ethereum-verified, but DA guarantees vary by configuration, materially affecting exit guarantees and risk.", "Primary User Type": "Teams seeking flexible cost/security trade-offs without abandoning Ethereum anchoring", "Production Usage Signal": "Active mainnet usage with growing interest in configurable DA deployments", "Protocol Ownership": "Core protocol stewarded by Matter Labs; ecosystem governance evolving", "Reason for Inclusion": "Implements a hybrid DA model where data availability placement is configurable, explicitly defining DA trust assumptions and enabling performance–security trade-offs without abandoning Ethereum settlement.", "Recovery Guarantees if DA Fails": "- Ethereum DA mode: full forced exit guarantees\n- Off-chain DA mode: limited; Ethereum cannot reconstruct state", "Rollup Variant": "Volition (hybrid rollup / validium)", "Security Lost vs Full Rollup": "Loss of Ethereum-guaranteed DA and forced exits in off-chain DA mode", "Settlement Layer": "Ethereum L1", "Throughput Improvements": "High in off-chain DA mode due to reduced calldata constraints", "Upgrade Authority": "Protocol upgrades governed centrally; deployment-level parameters configurable", "Use-Case Fit": "Gaming, consumer apps, enterprise workloads, and cost-sensitive applications needing ZK security", "User Exit Risk": "Conditional — absent in Ethereum DA mode; present in off-chain DA mode", "What Ethereum Verifies": "Validity proofs and state commitments (transaction data only when Ethereum DA is selected)", "Who Ultimately Controls DA": "Chain operators and governance, subject to zkSync protocol constraints"}, "source_label": "Validiums, Volitions, and Hybrid Rollups"}'::jsonb),
  ('immutable-x-production-nft-validium-using-starkex', 'Immutable X
(Production NFT validium using StarkEx)', 'rollup-scaling-frameworks', 'validiums-volitions-hybrid-rollups', 'https://www.immutable.com/immutable-x', ARRAY[]::text[], ARRAY[]::text[], '{"description": "A production ZK Validium built on StarkEx, optimized for NFTs and gaming. It anchors validity proofs and settlement to Ethereum while keeping data availability off-chain to minimize costs and maximize throughput.", "extras": {"Bridge Dependency": "Yes — required for all cross-ecosystem interaction", "Censorship Risk": "High — permissioned sequencing and DA", "Compatibility with Rollup": "Limited; requires bridges", "Composability with Ethereum": "Asynchronous; settlement only", "Cost Reduction vs Ethereum DA": "Very high (primary design goal)", "DA Committee Governance": "Highly centralized; operator-defined", "DA Location": "Off-chain (operator/committee-managed DA)", "DA Mode Switching": "Static (validium-only; no rollup mode)", "DA Provider Type": "Permissioned DA service coordinated by the operator (StarkEx DA model)", "DA Withholding Risk": "Yes — DA provider can withhold data", "Data Unavailability Scenarios": "DA service outage or malicious withholding", "Ecosystem Lock-in Risk": "High — tightly coupled to StarkEx and Immutable’s ecosystem", "Emergency Intervention Powers": "Strong operator-level pause and intervention controls", "Execution Proof Type": "ZK validity proofs (STARK-based)", "Failure Blast Radius": "Application-specific (isolated to Immutable X)", "Latency Characteristics": "Low latency due to off-chain DA and batching", "Longevity / Migration Risk": "Moderate — migration to a full rollup would require a DA and contract redesign", "Migration Path to Full Rollup": "Possible in theory, but operationally complex and disruptive", "Operational Complexity": "High — requires DA operations and coordination", "Practitioner Validation Check": "If Immutable X were removed, its NFT ecosystem would lose a StarkEx-based validium where DA lives off Ethereum and 